text:
Explore a single player’s profile across efficiency, shot volume, and made-shot location.






NoteInjury Note For Interpretation



Stephen Curry broke his left hand on October 30, 2019 (season 2019-20), underwent surgery, and missed 58 consecutive games.
He played only 5 games that season, briefly returned in March 2020, and Golden State finished 15-50.
Trend visuals mark 2019-20 so you can see the break in form and what happened around that season.



playerYear = await d3.csv("data/player_year.csv", d3.autoType)
madeShots = await d3.csv("data/made_shots.csv", d3.autoType)

players = Array.from(new Set(playerYear.map(d =&gt; d.player_name))).sort((a, b) =&gt; d3.ascending(a, b))

seasonMeta = Array.from(
  new Set(playerYear.map(d =&gt; +d.season))
).sort((a, b) =&gt; a - b).map(season =&gt; ({
  season,
  season_label: `${season}-${String((season + 1) % 100).padStart(2, "0")}`
}))

seasonLookup = new Map(seasonMeta.map(d =&gt; [d.season, d.season_label]))
seasonFromLabel = new Map(seasonMeta.map(d =&gt; [d.season_label, d.season]))
seasonLabels = seasonMeta.map(d =&gt; d.season_label)
injurySeason = 2019
injuryLabel = seasonLookup.get(injurySeason) ?? "2019-20"
injuryNote = `Injury context: broken left hand (${injuryLabel}), 58-game absence, 5 games played, Warriors 15-50.`

typeaheadInput = (options, {label, value, placeholder, maxSuggestions = 5}) =&gt; {
  const listId = `suggest-${Math.random().toString(36).slice(2, 10)}`
  const wrapper = html`&lt;label style="display:grid; gap:0.35rem;"&gt;
    &lt;span&gt;${label} (search)&lt;/span&gt;
    &lt;input type="text" list="${listId}" value="${value ?? ""}" placeholder="${placeholder ?? ""}" style="width:100%;"&gt;
    &lt;datalist id="${listId}"&gt;&lt;/datalist&gt;
    &lt;small style="opacity:0.75;"&gt;Top ${maxSuggestions} suggestions while typing&lt;/small&gt;
  &lt;/label&gt;`
  const input = wrapper.querySelector("input")
  const datalist = wrapper.querySelector("datalist")
  const optionStrings = options.map(option =&gt; String(option))

  const refreshSuggestions = () =&gt; {
    const query = input.value.trim().toLowerCase()
    const matches = optionStrings
      .filter(option =&gt; option.toLowerCase().includes(query))
      .slice(0, maxSuggestions)
    datalist.replaceChildren(...matches.map(match =&gt; html`&lt;option value="${match}"&gt;&lt;/option&gt;`))
  }

  const emitInput = () =&gt; {
    wrapper.value = input.value
    wrapper.dispatchEvent(new Event("input", {bubbles: true}))
  }

  input.addEventListener("input", () =&gt; {
    refreshSuggestions()
    emitInput()
  })
  input.addEventListener("change", emitInput)

  wrapper.value = input.value
  refreshSuggestions()
  return wrapper
}

adaptiveInput = (options, config) =&gt; (
  options.length &gt; 10
    ? typeaheadInput(options, config)
    : Inputs.select(options, {label: config.label, value: config.value})
)

resolveSearchValue = (inputValue, options, fallback) =&gt; {
  if (options.length === 0) return fallback ?? null
  const fallbackValue = options.includes(fallback) ? fallback : options[0]
  const query = String(inputValue ?? "").trim().toLowerCase()
  if (!query) return fallbackValue
  const exact = options.find(option =&gt; String(option).toLowerCase() === query)
  if (exact) return exact
  const partial = options.find(option =&gt; String(option).toLowerCase().includes(query))
  return partial ?? fallbackValue
}

defaultStartLabel = seasonLookup.get(2014) ?? seasonLabels[0]
defaultEndLabel = seasonLabels[seasonLabels.length - 1]

viewof selectedPlayerInput = adaptiveInput(players, {
  label: "Player",
  value: "Stephen Curry",
  placeholder: "Type player name..."
})
viewof seasonStartInput = adaptiveInput(seasonLabels, {
  label: "Season start",
  value: defaultStartLabel,
  placeholder: "Type season, e.g. 2019-20"
})
viewof seasonEndInput = adaptiveInput(seasonLabels, {
  label: "Season end",
  value: defaultEndLabel,
  placeholder: "Type season, e.g. 2020-21"
})

selectedPlayer = resolveSearchValue(selectedPlayerInput, players, "Stephen Curry")
seasonStartLabel = resolveSearchValue(seasonStartInput, seasonLabels, defaultStartLabel)
seasonEndLabel = resolveSearchValue(seasonEndInput, seasonLabels, defaultEndLabel)
seasonStart = seasonFromLabel.get(seasonStartLabel)
seasonEnd = seasonFromLabel.get(seasonEndLabel)
startSeason = Math.min(seasonStart, seasonEnd)
endSeason = Math.max(seasonStart, seasonEnd)
windowLabel = `${seasonLookup.get(startSeason)} to ${seasonLookup.get(endSeason)}`

playerTeams = ["All", ...Array.from(new Set(
  playerYear
    .filter(d =&gt; d.player_name === selectedPlayer)
    .map(d =&gt; d.team_name)
    .filter(Boolean)
)).sort((a, b) =&gt; d3.ascending(a, b))]

viewof teamFilterInput = adaptiveInput(playerTeams, {
  label: "Team filter",
  value: "All",
  placeholder: "Type team name..."
})

teamFilter = resolveSearchValue(teamFilterInput, playerTeams, "All")

inWindow = d =&gt; d.season &gt;= startSeason && d.season &lt;= endSeason
withTeam = d =&gt; teamFilter === "All" || d.team_name === teamFilter

playerRows = playerYear.filter(d =&gt; d.player_name === selectedPlayer && inWindow(d) && withTeam(d))
shotRows = madeShots.filter(d =&gt; d.player_name === selectedPlayer && inWindow(d) && withTeam(d))

summarize = rows =&gt; {
  const fga = d3.sum(rows, d =&gt; d.fga)
  const fgm = d3.sum(rows, d =&gt; d.fgm)
  const fga3 = d3.sum(rows, d =&gt; d.fga3)
  const fgm3 = d3.sum(rows, d =&gt; d.fgm3)
  const games = d3.sum(rows, d =&gt; d.games)
  return {
    fg_pct: fga &gt; 0 ? fgm / fga : NaN,
    tp_pct: fga3 &gt; 0 ? fgm3 / fga3 : NaN,
    efg: fga &gt; 0 ? (fgm + 0.5 * fgm3) / fga : NaN,
    tpa_per_game: games &gt; 0 ? fga3 / games : NaN,
    tpa_per_season: rows.length &gt; 0 ? fga3 / rows.length : NaN,
    fga_total: fga,
    fga3_total: fga3
  }
}

agg = summarize(playerRows)
fmtPct = v =&gt; Number.isFinite(v) ? d3.format(".1%")(v) : "n/a"
fmtNum = v =&gt; Number.isFinite(v) ? d3.format(".2f")(v) : "n/a"
fmtInt = v =&gt; Number.isFinite(v) ? d3.format(",.0f")(v) : "n/a"

md`
### ${selectedPlayer} (${windowLabel}) ${teamFilter === "All" ? "" : `| Team: ${teamFilter}`}

${injuryNote}

| Metric | Value |
|---|---:|
| FG% | ${fmtPct(agg.fg_pct)} |
| 3P% | ${fmtPct(agg.tp_pct)} |
| eFG% | ${fmtPct(agg.efg)} |
| 3PA / game | ${fmtNum(agg.tpa_per_game)} |
| 3PA / season | ${fmtNum(agg.tpa_per_season)} |
| Total FGA | ${fmtInt(agg.fga_total)} |
| Total 3PA | ${fmtInt(agg.fga3_total)} |
`



















































































































































































































































































Plot.plot({
  width: 930,
  height: 340,
  x: {label: "Season", tickFormat: d =&gt; seasonLookup.get(d) ?? String(d)},
  y: {label: "3PA per game"},
  marks: [
    Plot.ruleX([injurySeason], {stroke: "#d00000", strokeDasharray: "4,4"}),
    Plot.lineY(playerRows, {x: "season", y: "tpa_per_game", stroke: "#1f77b4", strokeWidth: 2}),
    Plot.dot(playerRows, {x: "season", y: "tpa_per_game", fill: "#1f77b4"})
  ]
})







Plot.plot({
  width: 930,
  height: 340,
  x: {label: "Season", tickFormat: d =&gt; seasonLookup.get(d) ?? String(d)},
  y: {label: "3P%", percent: true},
  marks: [
    Plot.ruleX([injurySeason], {stroke: "#d00000", strokeDasharray: "4,4"}),
    Plot.lineY(playerRows, {x: "season", y: "tp_pct", stroke: "#e76f51", strokeWidth: 2}),
    Plot.dot(playerRows, {x: "season", y: "tp_pct", fill: "#e76f51"})
  ]
})







arcPoints = (cx, cy, r, startDeg, endDeg, steps = 80) =&gt; {
  const pts = []
  const start = startDeg * Math.PI / 180
  const end = endDeg * Math.PI / 180
  for (let i = 0; i &lt;= steps; i++) {
    const t = start + (end - start) * (i / steps)
    pts.push({x: cx + r * Math.cos(t), y: cy + r * Math.sin(t)})
  }
  return pts
}

courtSegments = () =&gt; {
  const segs = []
  const pushLine = (a, b, id) =&gt; segs.push({id, points: [{x: a[0], y: a[1]}, {x: b[0], y: b[1]}]})

  pushLine([-25, 0], [25, 0], "baseline")
  pushLine([-25, 0], [-25, 47], "left_sideline")
  pushLine([25, 0], [25, 47], "right_sideline")
  pushLine([-25, 47], [25, 47], "halfcourt")

  pushLine([-8, 0], [-8, 19], "paint_left")
  pushLine([8, 0], [8, 19], "paint_right")
  pushLine([-8, 19], [8, 19], "paint_top")

  segs.push({id: "restricted", points: arcPoints(0, 5.25, 4, 0, 180, 70)})
  segs.push({id: "freethrow", points: arcPoints(0, 19, 6, 0, 360, 120)})
  pushLine([-22, 0], [-22, 14], "corner3_left")
  pushLine([22, 0], [22, 14], "corner3_right")
  segs.push({id: "arc3", points: arcPoints(0, 5.25, 23.75, 22, 158, 120)})

  return segs
}

segmentRows = courtSegments().flatMap(seg =&gt;
  seg.points.map((p, i) =&gt; ({id: seg.id, order: i, x: p.x, y: p.y}))
)

Plot.plot({
  width: 930,
  height: 520,
  subtitle: injuryNote,
  margin: 18,
  x: {domain: [-25, 25], axis: null},
  y: {domain: [0, 47], axis: null},
  marks: [
    Plot.line(segmentRows, {x: "x", y: "y", z: "id", stroke: "#8b8f93", strokeWidth: 1.1}),
    Plot.dot(shotRows, {
      x: "loc_x",
      y: "loc_y",
      r: 1.4,
      fill: "#1f77b4",
      opacity: 0.38,
      tip: true
    })
  ]
})






























zoneAgg = d3.rollups(
  shotRows,
  v =&gt; v.length,
  d =&gt; d.basic_zone
).map(([zone, count]) =&gt; ({zone, count})).sort((a, b) =&gt; b.count - a.count)

Plot.plot({
  width: 930,
  height: 340,
  subtitle: injuryNote,
  marginLeft: 180,
  x: {label: "Made shots"},
  y: {label: null},
  marks: [
    Plot.barX(zoneAgg, {x: "count", y: "zone", fill: "#457b9d"}),
    Plot.text(zoneAgg, {
      x: "count",
      y: "zone",
      text: d =&gt; d.count.toLocaleString(),
      dx: 6,
      textAnchor: "start"
    })
  ]
})

