typeaheadInput = (options, {label, value, placeholder, maxSuggestions = 5}) =&gt; {
  const listId = `suggest-${Math.random().toString(36).slice(2, 10)}`
  const wrapper = html`&lt;label style="display:grid; gap:0.35rem;"&gt;
    &lt;span&gt;${label} (search)&lt;/span&gt;
    &lt;input type="text" list="${listId}" value="${value ?? ""}" placeholder="${placeholder ?? ""}" style="width:100%;"&gt;
    &lt;datalist id="${listId}"&gt;&lt;/datalist&gt;
    &lt;small style="opacity:0.75;"&gt;Top ${maxSuggestions} suggestions while typing&lt;/small&gt;
  &lt;/label&gt;`
  const input = wrapper.querySelector("input")
  const datalist = wrapper.querySelector("datalist")
  const optionStrings = options.map(option =&gt; String(option))

  const refreshSuggestions = () =&gt; {
    const query = input.value.trim().toLowerCase()
    const matches = optionStrings
      .filter(option =&gt; option.toLowerCase().includes(query))
      .slice(0, maxSuggestions)
    datalist.replaceChildren(...matches.map(match =&gt; html`&lt;option value="${match}"&gt;&lt;/option&gt;`))
  }

  const emitInput = () =&gt; {
    wrapper.value = input.value
    wrapper.dispatchEvent(new Event("input", {bubbles: true}))
  }

  input.addEventListener("input", () =&gt; {
    refreshSuggestions()
    emitInput()
  })
  input.addEventListener("change", emitInput)

  wrapper.value = input.value
  refreshSuggestions()
  return wrapper
}

adaptiveInput = (options, config) =&gt; (
  options.length &gt; 10
    ? typeaheadInput(options, config)
    : Inputs.select(options, {label: config.label, value: config.value})
)

resolveSearchValue = (inputValue, options, fallback) =&gt; {
  if (options.length === 0) return fallback ?? null
  const fallbackValue = options.includes(fallback) ? fallback : options[0]
  const query = String(inputValue ?? "").trim().toLowerCase()
  if (!query) return fallbackValue
  const exact = options.find(option =&gt; String(option).toLowerCase() === query)
  if (exact) return exact
  const partial = options.find(option =&gt; String(option).toLowerCase().includes(query))
  return partial ?? fallbackValue
}

